css:
.twitter-card {
  width: 320px;
  background: black;
  border-radius: 16px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  /* Thick black border effect */
  border: 4px solid #000;
  /* Additional shadow for depth */
  box-shadow: 8px 8px 0px #000;
  position: relative;
  margin: 20px;
}

.card-header {
  background: linear-gradient(90deg, #5f72ff, #9a4eff);
  color: white;
  padding: 24px 20px;
  position: relative;
}

.header-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.twitter-icon {
  width: 28px;
  height: 28px;
  fill: white;
}

.status {
  background: rgba(255, 255, 255, 0.25);
  padding: 6px 14px;
  border-radius: 16px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.brand-name {
  font-size: 28px;
  font-weight: bold;
  margin-bottom: 6px;
  letter-spacing: -0.5px;
}

.handle {
  font-size: 16px;
  opacity: 0.9;
  font-weight: 400;
}

.card-stats {
  padding: 24px 20px;
  display: flex;
  justify-content: space-between;
  background: white;
}

.stat {
  text-align: center;
  flex: 1;
  padding: 0 8px;
}

.stat-number {
  font-size: 20px;
  font-weight: bold;
  color: #14171a;
  margin-bottom: 6px;
  line-height: 1;
}

.stat-label {
  font-size: 13px;
  color: #657786;
  font-weight: 500;
  text-transform: capitalize;
}

.stat:not(:last-child) {
  border-right: 1px solid #e1e8ed;
}

/* Hover effect for the entire card */
.twitter-card:hover {
  transform: translate(-2px, -2px);
  box-shadow: 10px 10px 0px #000;
  transition: all 0.2s ease;
}

@media (max-width: 480px) {
  .twitter-card {
    width: 300px;
    border: 3px solid #000;
    box-shadow: 6px 6px 0px #000;
  }

  .twitter-card:hover {
    box-shadow: 8px 8px 0px #000;
  }

  .brand-name {
    font-size: 24px;
  }

  .stat-number {
    font-size: 18px;
  }

  .stat-label {
    font-size: 12px;
  }
}
